import json

ai = node_outputs.get('ai_action', {})
status = ai.get('status', None)
raw = ai.get('data', '')
answer = ''

if isinstance(raw, str):
    answer = raw
elif isinstance(raw, dict):
    choices = raw.get('choices')
    if isinstance(choices, list) and len(choices) > 0:
        parts = []
        for c in choices:
            if isinstance(c, dict):
                msg = c.get('message') or c.get('delta') or {}
                if isinstance(msg, dict):
                    part = msg.get('content') or msg.get('text') or ''
                else:
                    part = c.get('text', '')
                if not part:
                    part = c.get('text', '')
                if part:
                    parts.append(part)
        if parts:
            answer = "\n".join(parts)
        else:
            answer = raw.get('text', json.dumps(raw, ensure_ascii=False))
    else:
        if 'message' in raw and isinstance(raw.get('message'), dict):
            answer = raw.get('message', {}).get('content', '')
        elif 'text' in raw:
            answer = raw.get('text', '')
        else:
            answer = json.dumps(raw, ensure_ascii=False)
elif isinstance(raw, list):
    items = []
    for it in raw:
        items.append(it if isinstance(it, str) else json.dumps(it, ensure_ascii=False))
    answer = "\n".join(items)
else:
    answer = str(raw)

output = {}
output['status'] = status
output['success'] = ai.get('success', True if status == 200 else False)
output['answer'] = answer
output['raw'] = raw
